<template><main class="myblugs-page"><NavBar/><AdSlot class="page-banner" placement="banner"/><div class="myblugs-workspace"><aside class="page-ad-rail"><AdSlot placement="sidebar"/><AdSlot placement="sidebar"/><AdSlot placement="sidebar"/></aside><section class="myblugs-main"><header><div><span class="eyebrow">Your blug library</span><h1>My blugs</h1><p>{{ posts.length }} published blugs</p></div><button @click="router.push('/create-blog')">+ New blug</button></header><label class="mobile-search"><span aria-hidden="true">⌕</span><input v-model="search" aria-label="Search your blugs" placeholder="Search your blugs"/></label><div class="post-list"><article v-for="post in filteredPosts" :key="post.id"><button class="cover-link" :aria-label="`Read ${post.title}`" @click="open(post.id)"><img :src="cover(post)" :alt="`Cover for ${post.title}`"/></button><div class="post-copy"><span>{{post.categories||'Blugs'}} · {{new Date(post.created_at).toLocaleDateString()}}</span><h2><button class="post-title" @click="open(post.id)">{{post.title}}</button></h2><p>{{excerpt(post.content)}}</p><footer><button @click="router.push(`/edit/${post.id}`)">Edit</button><button class="delete" @click="remove(post.id)">Delete</button><button class="view" @click="open(post.id)">View blug →</button></footer></div></article><p v-if="!filteredPosts.length" class="empty">No blugs match your search.</p></div></section><aside class="myblugs-rail"><label><span aria-hidden="true">⌕</span><input v-model="search" aria-label="Search your blugs" placeholder="Search your blugs"/></label><section><h3>Manage your blugs</h3><p>Edit published blugs, review how they appear to readers, or start a new blug.</p><button @click="router.push('/create-blog')">Write a new blug</button></section><AdSlot placement="sidebar"/></aside></div></main></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRouter}from'vue-router';import NavBar from'./NavBar.vue';import AdSlot from'./AdSlot.vue';import{deletePost,listPosts}from'../api/posts';import{authStore}from'../stores/auth';import type{LocalPost}from'../api/types';const posts=ref<LocalPost[]>([]),search=ref(''),router=useRouter();const filteredPosts=computed(()=>{const term=search.value.toLowerCase();return posts.value.filter(post=>!term||`${post.title} ${post.categories} ${post.content}`.toLowerCase().includes(term));});const load=async()=>{const id=authStore.user.value?.id;if(id)posts.value=(await listPosts(id)).posts};const remove=async(id:string)=>{if(!confirm('Delete this blug?'))return;await deletePost(id);await load()};const open=(id:string)=>router.push({name:'SharedBlug',params:{blogId:id}});const excerpt=(html:string)=>html.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,150)+'…';const cover=(post:LocalPost)=>post.header_image_url||(post.id.length%2?'/blug_default.png':'/blug_default_2.webp');onMounted(load);</script>
<style scoped>.myblugs-page{min-height:100vh;padding:112px 22px 90px}.myblugs-workspace{display:grid;grid-template-columns:minmax(0,1fr) 290px;width:min(1120px,100%);margin:auto;border:1px solid rgba(255,255,255,.16);border-radius:28px;background:rgba(79,71,74,.62);backdrop-filter:blur(24px);overflow:hidden}.myblugs-main{padding:28px 30px 40px;border-right:1px solid rgba(255,255,255,.14)}.myblugs-main>header{display:flex;align-items:end;justify-content:space-between;padding-bottom:22px;border-bottom:1px solid var(--line)}h1{margin:6px 0 3px;font:700 clamp(2.2rem,5vw,3.4rem)/1 Georgia}.myblugs-main>header p{margin:0;color:var(--muted);font-size:.72rem}.myblugs-main>header button,.myblugs-rail section button{padding:10px 14px;border:0;border-radius:10px;background:var(--orange);color:#fff;font-weight:800}.post-list article{display:grid;grid-template-columns:180px minmax(0,1fr);gap:18px;padding:20px 0;border-bottom:1px solid var(--line)}.post-list article>img{width:100%;height:125px;border-radius:13px;object-fit:cover;cursor:pointer}.post-copy>span{color:#a99aff;font-size:.65rem;font-weight:800;text-transform:uppercase}.post-copy h2{margin:7px 0;font:700 1.25rem Georgia;cursor:pointer}.post-copy p{display:-webkit-box;overflow:hidden;margin:0;color:var(--muted);font-size:.78rem;line-height:1.5;-webkit-box-orient:vertical;-webkit-line-clamp:2}.post-copy footer{display:flex;gap:8px;margin-top:12px}.post-copy footer button{padding:6px 10px;border:0;border-radius:8px;background:rgba(239,225,216,.14);color:#fff;font-size:.67rem}.post-copy footer .delete{color:#ffaaa0}.post-copy footer .view{margin-left:auto;background:none}.myblugs-rail{display:grid;align-content:start;gap:24px;padding:28px 20px}.myblugs-rail>label,.mobile-search{display:flex;gap:8px;padding:10px 12px;border-radius:10px;background:rgba(32,28,31,.48)}.myblugs-rail input,.mobile-search input{width:100%;border:0;outline:0;background:none;color:#fff}.myblugs-rail section{padding-top:20px;border-top:1px solid var(--line)}.myblugs-rail h3{margin:0;font-size:.9rem}.myblugs-rail p{color:var(--muted);font-size:.76rem;line-height:1.55}.myblugs-rail section button{font-size:.68rem}.mobile-search{display:none}.empty{padding:60px;text-align:center;color:var(--muted)}@media(max-width:800px){.myblugs-page{padding:86px 0 80px}.myblugs-workspace{display:block;border-left:0;border-right:0;border-radius:0}.myblugs-main{padding:24px 15px;border:0}.myblugs-rail{display:none}.mobile-search{display:flex;margin:16px 0}.post-list article{grid-template-columns:100px minmax(0,1fr);gap:12px}.post-list article>img{height:90px}.post-copy p{display:none}.post-copy h2{font-size:1rem}.post-copy footer .view{display:none}}</style>
